from collections import Counter, defaultdict, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                x, y = q.popleft()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if (0 <= a < h and 0 <= b < w and (a, b) not in seen
                            and grid[a][b] == color):
                        seen.add((a, b))
                        cells.add((a, b))
                        q.append((a, b))
            result.append({"color": color, "cells": cells})
    return result


def _corner_l(comp, h, w):
    cells = comp["cells"]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    if r0 == r1 or c0 == c1:
        return False
    for rb in (r0, r1):
        for cb in (c0, c1):
            shape = ({(rb, c) for c in range(c0, c1 + 1)}
                     | {(r, cb) for r in range(r0, r1 + 1)})
            if cells != shape:
                continue
            horizontal_tip = (rb, c0 if cb == c1 else c1)
            vertical_tip = (r0 if rb == r1 else r1, cb)
            if (horizontal_tip[1] in (0, w - 1)
                    and vertical_tip[0] in (0, h - 1)):
                return True
    return False


def _signature(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return tuple(sorted((r - r0, c - c0) for r, c in cells))


def _min_distance(a, b):
    return min(abs(r - rr) + abs(c - cc)
               for r, c in a["cells"] for rr, cc in b["cells"])


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    comps = _components(grid, background)
    keys = [obj for obj in comps if _corner_l(obj, h, w)]
    if not keys:
        return [row[:] for row in grid]
    key = keys[0]

    # The L-shaped marker identifies the board corner that it touches.
    key_rs = [r for r, c in key["cells"]]
    key_cs = [c for r, c in key["cells"]]
    corner = (0 if min(key_rs) == 0 else h - 1,
              0 if min(key_cs) == 0 else w - 1)

    # Find a repeated motif with one copy nearest the marker's board corner.
    by_shape = defaultdict(list)
    for obj in comps:
        if obj is not key:
            by_shape[_signature(obj["cells"])].append(obj)
    groups = [group for group in by_shape.values() if len(group) >= 2]
    if not groups:
        return [row[:] for row in grid]

    def corner_distance(obj):
        return min(abs(r - corner[0]) + abs(c - corner[1])
                   for r, c in obj["cells"])

    group = min(groups, key=lambda g: min(corner_distance(obj) for obj in g))
    target = max(group, key=corner_distance)

    out = [row[:] for row in grid]
    for r, c in target["cells"]:
        out[r][c] = key["color"]
    return out
